<?php $waiverData=input($_POST,'action')==='donation-waiver-save'&&is_array($_POST['data']??null)?$_POST['data']:[];$waiverDocuments=array_filter((new \Kulturhus\Verein\Documents($db,(string)$_SESSION['actor']))->listing(),static fn($d)=>$d['state']==='active'&&in_array('finance',$d['scopes'],true)); ?>
<details class="card" <?= input($_POST,'action')==='donation-waiver-save'?'open':'' ?>><summary><?= $ct('Aufwandsverzicht mit Nachweisen erfassen') ?></summary><p><?= $ct('Nur ein bereits vorher eingeräumter, ernsthafter und werthaltiger Anspruch kommt infrage. Arbeitszeit allein ist keine Geldspende. Der Verzicht erzeugt hier keinen Bankumsatz. Lade die Anspruchsgrundlage und die Verzichtserklärung zuerst in die Finanzablage.') ?></p><form method="post"><?= csrf().hidden('action','donation-waiver-save').hidden('request_key',input($_POST,'request_key',bin2hex(random_bytes(16)))) ?>
<label><?= $ct('Zuwender') ?><select class="form-control" name="data[contact_id]" required><option value=""><?= $ct('Bitte auswählen') ?></option><?php foreach($waiverService->contacts() as $person): ?><option value="<?= e($person['id']) ?>" <?= $person['id']===input($waiverData,'contact_id',$collectionContact)?'selected':'' ?>><?= e($person['name']) ?></option><?php endforeach ?></select></label>
<div class="form-grid"><?php foreach(['amount'=>$collectionText('Anspruchsbetrag in Euro'),'agreed_on'=>$collectionText('Anspruch vorher vereinbart am'),'incurred_on'=>$collectionText('Aufwand entstanden am'),'due_on'=>$collectionText('Anspruch fällig am'),'waived_on'=>$collectionText('Verzicht erklärt am')] as $key=>$label): ?><label><?= $ct($label) ?><input class="form-control" name="data[<?= $key ?>]" type="<?= $key==='amount'?'text':'date' ?>" <?= $key==='amount'?'inputmode="decimal"':'max="'.date('Y-m-d').'"' ?> value="<?= e(input($waiverData,$key)) ?>" required></label><?php endforeach ?></div>
<label><?= $ct('Tätigkeit') ?><select class="form-control" name="data[regular]"><option value="0"><?= $ct('Einmaliger Anspruch') ?></option><option value="1" <?= input($waiverData,'regular')==='1'?'selected':'' ?>><?= $ct('Regelmäßig monatliche Tätigkeit') ?></option></select></label>
<?php foreach(['claim_document_id'=>$collectionText('Nachweis des vorher vereinbarten Anspruchs'),'waiver_document_id'=>$collectionText('Nachweis der Verzichtserklärung')] as $key=>$label): ?><label><?= $ct($label) ?><select class="form-control" name="data[<?= $key ?>]" required><option value=""><?= $ct('Bitte auswählen') ?></option><?php $oldDocument=input($waiverData,$key);if($oldDocument!==''&&!in_array($oldDocument,array_column($waiverDocuments,'id'),true)): ?><option value="<?= e($oldDocument) ?>" selected><?= $ct($collectionText('Ursprünglicher Nachweis – aktuell nicht verfügbar:')) ?> <?= e($oldDocument) ?></option><?php endif ?><?php foreach($waiverDocuments as $doc): ?><option value="<?= e($doc['id']) ?>" <?= $doc['id']===input($waiverData,$key)?'selected':'' ?>><?= e($doc['title']) ?></option><?php endforeach ?></select></label><?php endforeach ?>
<label><?= $ct('Anspruch und tatsächlichen Aufwand beschreiben') ?><textarea class="form-control" name="data[description]" maxlength="2000" required><?= e(input($waiverData,'description')) ?></textarea></label>
<?php foreach(['unconditional'=>$collectionText('Der Anspruch wurde vor der Tätigkeit eingeräumt und war nicht bereits vom Verzicht abhängig.'),'payable_when_granted'=>$collectionText('Der Verein konnte die Verpflichtung bei Einräumung des Anspruchs erfüllen.'),'payable_when_waived'=>$collectionText('Der Anspruch war beim Verzicht noch werthaltig.'),'reviewed'=>$collectionText('Ich habe Anspruch, Belege und freiwilligen zeitnahen Verzicht fachlich geprüft.')] as $key=>$label): ?><label class="check"><input class="check" type="checkbox" name="data[<?= $key ?>]" value="1" required <?= input($waiverData,$key)==='1'?'checked':'' ?>><?= $ct($label) ?></label><?php endforeach ?><button class="btn btn-solid theme-primary"><?= $ct('Aufwandsverzicht mit Nachweisen speichern') ?></button></form></details>
<section class="card"><h2><?= $ct('Erfasste Aufwandsverzichte') ?></h2><?php foreach($waiverService->listing() as $waiver): ?><details <?= input($_POST,'action')==='donation-waiver-cancel'&&input($_POST,'id')===$waiver['id']?'open':'' ?>><summary><?= e($waiver['name'].' · '.$waiver['waived_on'].' · '.number_format($waiver['amount_cents']/100,2,',','.').' €'.($waiver['cancelled_at']?' · '.$collectionText('Storniert'):'')) ?></summary><p><?= e($waiver['cancel_reason']??'') ?></p><a href="<?= e(url(['document_file'=>$waiver['claim_document_id']])) ?>"><?= $ct('Anspruchsnachweis öffnen') ?></a> · <a href="<?= e(url(['document_file'=>$waiver['waiver_document_id']])) ?>"><?= $ct('Verzichtsnachweis öffnen') ?></a><?php if(!$waiver['cancelled_at']): ?><form method="post"><?= csrf().hidden('action','donation-waiver-cancel').hidden('id',$waiver['id']).hidden('version',$waiver['version']) ?><label><?= $ct('Stornogrund') ?><textarea class="form-control" name="reason" maxlength="1000" required><?= e(input($_POST,'id')===$waiver['id']?input($_POST,'reason'):'') ?></textarea></label><button class="btn btn-outline theme-secondary secondary"><?= $ct('Aufwandsverzicht stornieren') ?></button></form><?php endif ?></details><?php endforeach ?></section>
